26	        expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
27	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
28	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
29	    @Mapping(target = "locality",
30	        expression = "java(org.springframework.samples.petclinic.util.Localities.regionFor(owner.getCity(), owner.getPostcode()))")
31	    @Mapping(target = "contactPreference",
32	        expression = "java(owner.getEmail() != null ? \"EMAIL\" : \"PHONE\")")
33	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
34	    OwnerDto toOwnerDto(Owner owner);
35	
36	    /** The single duplicate-detection key: normalizedTelephone + '|' + (email or empty) + '|' + (householdId or empty). */
37	    default String identityKey(Owner owner) {
38	        return orEmpty(owner.getTelephone()) + '|' + orEmpty(owner.getEmail()) + '|' + orEmpty(owner.getHouseholdId());
39	    }
40	
41	    default String orEmpty(String value) {
42	        return value == null ? "" : value;
43	    }
44	
45	    /** Numeric level 1-3: starts at 1, +1 for an email, +1 when namesakeCount is 0, capped at 3 (level 4 reserved for tenure). */
46	    default Integer membershipLevel(Owner owner) {
47	        int level = 1;
48	        if (owner.getEmail() != null) {
49	            level++;
50	        }
51	        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
52	            level++;
53	        }
54	        return Math.min(level, 3);
55	    }
56	
57	    /** Derive the '<customerCode>-M<YY>' membership number, where YY is the last two digits of the registrationDate year. */
58	    default String membershipNumber(Owner owner) {
59	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
60	            return null;
61	        }
62	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
63	    }
64	
65	    Owner toOwner(OwnerDto ownerDto);
66	
67	    @Mapping(target = "id", ignore = true)
68	    @Mapping(target = "pets", ignore = true)
69	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
70	    @Mapping(target = "registrationDate", expression = "java(effectiveRegistrationDate(ownerDto))")
71	    Owner toOwner(OwnerFieldsDto ownerDto);
72	
73	    /** The supplied registration date, or today's date when absent, rolled forward off weekends to a business day. */
74	    default java.time.LocalDate effectiveRegistrationDate(OwnerFieldsDto ownerDto) {
75	        java.time.LocalDate supplied = ownerDto.getRegistrationDate();
76	        return org.springframework.samples.petclinic.util.BusinessDays.toBusinessDay(
77	            supplied != null ? supplied : java.time.LocalDate.now());
78	    }
79	
80	    /** Normalize to E.164 so the create path stores, and duplicate detection compares, that form. */
81	    @Named("normalizeTelephone")
82	    default String normalizeTelephone(String telephone) {
83	        return TelephoneNormalizer.toE164(telephone);
84	    }
85	
86	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
87	
88	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
89	
90	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
91	        OwnerPageDto ownerPageDto = new OwnerPageDto();
92	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
93	        ownerPageDto.setPage(ownerPage.getNumber());
94	        ownerPageDto.setSize(ownerPage.getSize());
95	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
96	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
97	        return ownerPageDto;
98	    }
99	}
