36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be valid E.164")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    private String email;
54	
55	    @Column(name = "postcode")
56	    private String postcode;
57	
58	    @Column(name = "registration_date", columnDefinition = "DATE")
59	    private java.time.LocalDate registrationDate;
60	
61	    @Column(name = "customer_code")
62	    private String customerCode;
63	
64	    @Column(name = "household_id")
65	    private String householdId;
66	
67	    @Column(name = "namesake_count")
68	    private Integer namesakeCount;
69	
70	    @Column(name = "household_member_count")
71	    private Integer householdMemberCount;
72	
73	    public String getCustomerCode() {
74	        return this.customerCode;
75	    }
76	
77	    public Integer getNamesakeCount() {
78	        return this.namesakeCount;
79	    }
80	
81	    public void setNamesakeCount(Integer namesakeCount) {
82	        this.namesakeCount = namesakeCount;
83	    }
84	
85	    /** Record how many of {@code existingOwners} share this owner's first and last name, case-insensitively. */
86	    public void assignNamesakeCount(Collection<Owner> existingOwners) {
87	        int count = 0;
88	        for (Owner other : existingOwners) {
89	            if (getFirstName().equalsIgnoreCase(other.getFirstName())
90	                && getLastName().equalsIgnoreCase(other.getLastName())) {
91	                count++;
92	            }
93	        }
94	        this.namesakeCount = count;
95	        assignHouseholdMemberCount(existingOwners);
96	    }
97	
98	    public Integer getHouseholdMemberCount() {
99	        return this.householdMemberCount;
100	    }
101	
102	    /** Record how many owners (this one included) share this owner's household after this create. */
103	    public void assignHouseholdMemberCount(Collection<Owner> existingOwners) {
104	        int count = 1;
105	        for (Owner other : existingOwners) {
106	            if (householdId != null && householdId.equals(other.getHouseholdId())) {
107	                count++;
108	            }
109	        }
110	        this.householdMemberCount = count;
111	    }
