182	    protected Set<Pet> getPetsInternal() {
183	        if (this.pets == null) {
184	            this.pets = new HashSet<>();
185	        }
186	        return this.pets;
187	    }
188	
189	    protected void setPetsInternal(Set<Pet> pets) {
190	        this.pets = pets;
191	    }
192	
193	    public List<Pet> getPets() {
194	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
195	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
196	        return Collections.unmodifiableList(sortedPets);
197	    }
198	
199	    public void setPets(List<Pet> pets) {
200	        this.pets = new HashSet<>(pets);
201	    }
202	
203	    public void addPet(Pet pet) {
204	        getPetsInternal().add(pet);
205	        pet.setOwner(this);
206	    }
207	
208	    /**
209	     * Return the Pet with the given name, or null if none found for this Owner.
210	     *
211	     * @param name to test
212	     * @return true if pet name is already in use
213	     */
214	    public Pet getPet(String name) {
215	        return getPet(name, false);
216	    }
217	
218	    /**
219	     * Return the Pet with the given name, or null if none found for this Owner.
220	     *
221	     * @param name to test
222	     * @return true if pet name is already in use
223	     */
224	    public Pet getPet(String name, boolean ignoreNew) {
225	        name = name.toLowerCase();
226	        for (Pet pet : getPetsInternal()) {
227	            if (!ignoreNew || !pet.isNew()) {
228	                String compName = pet.getName();
229	                compName = compName.toLowerCase();
230	                if (compName.equals(name)) {
231	                    return pet;
232	                }
233	            }
234	        }
235	        return null;
236	    }
237	
238	    public Pet getPet(Integer petId) {
239	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
240	    }
