52	 * ({@code normalizedTelephone + '|' + (email or empty) + '|' + (householdId or empty)}) equals an
53	 * existing owner's, responding 409 Conflict. This single derived key subsumes the former separate
54	 * telephone, email and household duplicate checks: because the telephone is part of the key, two
55	 * members of the same household with different telephones have different keys and are both allowed;
56	 * only an exact full-key match is a duplicate. The {@code sharesHousehold} flag still assigns a
57	 * shared householdId, read from the raw body which is buffered and re-supplied downstream.
58	 */
59	@ControllerAdvice
60	@Order(Ordered.HIGHEST_PRECEDENCE)
61	public class OwnerUniqueIdentityAdvice implements RequestBodyAdvice {
62	
63	    private final ClinicService clinicService;
64	
65	    private final OwnerMapper ownerMapper;
66	
67	    private final ObjectMapper objectMapper;
68	
69	    public OwnerUniqueIdentityAdvice(ClinicService clinicService, OwnerMapper ownerMapper, ObjectMapper objectMapper) {
70	        this.clinicService = clinicService;
71	        this.ownerMapper = ownerMapper;
72	        this.objectMapper = objectMapper;
73	    }
74	
75	    @Override
76	    public boolean supports(MethodParameter methodParameter, Type targetType,
77	                            Class<? extends HttpMessageConverter<?>> converterType) {
78	        Method method = methodParameter.getMethod();
79	        return OwnerFieldsDto.class.equals(targetType) && method != null
80	            && "addOwner".equals(method.getName());
81	    }
82	
83	    @Override
84	    public HttpInputMessage beforeBodyRead(HttpInputMessage inputMessage, MethodParameter parameter,
85	                                           Type targetType, Class<? extends HttpMessageConverter<?>> converterType)
86	            throws IOException {
87	        byte[] bytes = inputMessage.getBody().readAllBytes();
88	        JsonNode body = objectMapper.readTree(bytes);
89	        if (body.path("sharesHousehold").asBoolean(false)) {
90	            ((ObjectNode) body).put("householdId",
91	                householdId(body.path("lastName").asString(""), body.path("address").asString("")));
92	            bytes = objectMapper.writeValueAsBytes(body);
