97	    /** Stable identifier shared by every owner with the same normalized lastName and address. */
98	    private String householdId(String lastName, String address) {
99	        String key = name(lastName) + '\n' + AddressNormalizer.normalize(address);
100	        return UUID.nameUUIDFromBytes(key.getBytes(StandardCharsets.UTF_8)).toString();
