126	        return new HttpInputMessage() {
127	            @Override
128	            public InputStream getBody() {
129	                return new ByteArrayInputStream(bytes);
130	            }
131	
132	            @Override
133	            public HttpHeaders getHeaders() {
134	                return headers;
135	            }
136	        };
137	    }
138	
139	    @ExceptionHandler(DuplicateIdentityException.class)
140	    @ResponseBody
141	    public ResponseEntity<Void> handleDuplicateIdentity(DuplicateIdentityException e) {
142	        return ResponseEntity.status(HttpStatus.CONFLICT).build();
143	    }
