43	@ControllerAdvice
44	@Order(Ordered.HIGHEST_PRECEDENCE)
45	public class OwnerTelephoneLengthAdvice implements RequestBodyAdvice {
46	
47	    /** Country code (with leading '+') -> required national-number digit count. */
48	    private static final Map<String, Integer> NATIONAL_LENGTH = Map.of("+61", 9, "+1", 10);
49	
50	    private final OwnerMapper ownerMapper;
51	
52	    public OwnerTelephoneLengthAdvice(OwnerMapper ownerMapper) {
